import { ArrowDown, ArrowLeft, ArrowRight, ArrowUp, AudioLines, BookOpen, Check, CheckCircle2, ChevronDown, ChevronRight, Circle, CircleHelp, Cloud, CloudUpload, Download, Ellipsis, FileText, FolderOpen, HardDrive, LayoutDashboard, Library, LoaderCircle, Mic, Monitor, MousePointer2, MoveUpRight, Pause, Play, Plus, Search, Settings2, ShieldCheck, Sparkles, Square, SquareDashed, Trash2, Upload, Users, Video, Volume2, WandSparkles, X, EyeOff, Undo2, Keyboard, Copy, ExternalLink } from 'lucide-react';
