type Tool='select'|Annotation['type'];
const STATUS={draft:'Rascunho',published:'Publicado',recording:'Gravando',interrupted:'Recuperado'};
const PROVIDER_NAMES={browser:'Voz do navegador',windows:'Voz do Windows',gemini:'Gemini API',openai:'OpenAI API'};
function useAsset(assetId?:string){
  const [url,setUrl]=useState('');
  useEffect(()=>{let cancelled=false;let objectUrl='';let timer:ReturnType<typeof setTimeout>;let attempt=0;setUrl('');
    const read=async()=>{const asset=await getAsset(assetId);if(cancelled)return;if(asset){objectUrl=URL.createObjectURL(asset.blob);setUrl(objectUrl);}else if(assetId&&attempt++<20)timer=setTimeout(read,150);};void read();
    return()=>{cancelled=true;clearTimeout(timer);if(objectUrl)URL.revokeObjectURL(objectUrl);};
  },[assetId]);return url;
}
function AssetImage({assetId,...props}:{assetId?:string}&React.ImgHTMLAttributes<HTMLImageElement>){const url=useAsset(assetId);return url?<img src={url} {...props}/>:<div className="image-skeleton"><Monitor size={26}/></div>;}
function AssetMedia({assetId,type,audioRef}:{assetId?:string;type:'audio'|'video';audioRef?:React.RefObject<HTMLAudioElement|null>}){const url=useAsset(assetId);return url?type==='audio'?<audio ref={audioRef} controls src={url}/>:<video controls src={url} playsInline/>:null;}
function Modal({title,subtitle,children,onClose,wide=false}:{title:string;subtitle?:string;children:React.ReactNode;onClose:()=>void;wide?:boolean}){
  const dialog=useRef<HTMLDialogElement>(null);
  useEffect(()=>{const node=dialog.current!;node.showModal();return()=>node.close();},[]);
  return <dialog ref={dialog} className={`modal ${wide?'modal-wide':''}`} onCancel={onClose} onClick={e=>{if(e.target===dialog.current){const r=dialog.current.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)onClose();}}}><div className="modal-head"><div><h2>{title}</h2>{subtitle&&<p>{subtitle}</p>}</div><button className="icon-button" aria-label="Fechar" onClick={onClose}><X size={20}/></button></div>{children}</dialog>;
}
function Annotations({annotations,draft}:{annotations:Annotation[];draft?:Annotation}){
  return <svg className="annotation-layer" viewBox="0 0 1000 1000" preserveAspectRatio="none" aria-hidden="true"><defs><marker id="arrowhead" markerWidth="10" markerHeight="10" refX="8" refY="3" orient="auto" markerUnits="strokeWidth"><path d="M0,0 L0,6 L9,3 z" fill="#348fff"/></marker></defs>{[...annotations,...(draft?[draft]:[])].map(a=>{const x=a.x*1000,y=a.y*1000,x2=a.x2*1000,y2=a.y2*1000;return <g key={a.id} stroke="#348fff" strokeWidth="3" fill="none" vectorEffect="non-scaling-stroke">
    {a.type==='circle'&&<ellipse cx={(x+x2)/2} cy={(y+y2)/2} rx={Math.max(3,Math.abs(x2-x)/2)} ry={Math.max(3,Math.abs(y2-y)/2)} vectorEffect="non-scaling-stroke"/>}
    {['box','blur'].includes(a.type)&&<rect x={Math.min(x,x2)} y={Math.min(y,y2)} width={Math.abs(x2-x)} height={Math.abs(y2-y)} fill={a.type==='blur'?'#111827':'none'} vectorEffect="non-scaling-stroke"/>}
    {a.type==='arrow'&&<line x1={x} y1={y} x2={x2} y2={y2} markerEnd="url(#arrowhead)" vectorEffect="non-scaling-stroke"/>}
    {a.text&&<g stroke="none"><rect x={x} y={Math.max(0,y-34)} width={Math.min(950-x,a.text.length*11+20)} height="32" rx="4" fill="#176bdb"/><text x={x+9} y={Math.max(22,y-12)} fill="white" fontSize="20" fontFamily="sans-serif">{a.text}</text></g>}
  </g>;})}</svg>;
}

function SettingsModal({config,refresh,onClose,notify}:{config:Config;refresh:()=>Promise<void>;onClose:()=>void;notify:(s:string)=>void}){
  const [tab,setTab]=useState('voice');const [provider,setProvider]=useState<Provider>(config.provider);const [key,setKey]=useState('');const [model,setModel]=useState(config.model);const [liveModel,setLiveModel]=useState(config.liveModel);const [consent,setConsent]=useState(config.consent);const [busy,setBusy]=useState(false);const [clientId,setClientId]=useState(localStorage.getItem('playbook-google-client-id')||config.googleClientId);const [connected,setConnected]=useState(driveConnected());const [driveFiles,setDriveFiles]=useState<{id:string;name:string;modifiedTime:string}[]>([]);
  const run=async(fn:()=>Promise<void>)=>{setBusy(true);try{await fn();}catch(e){notify((e as Error).message);}finally{setBusy(false);}};
  const save=async()=>{await api('/api/config',{provider,...(key?{apiKey:key}:{}),model,liveModel,consent});setKey('');await refresh();};
  return <Modal title="Seu estúdio, do seu jeito" subtitle="Conexões, transcrição e armazenamento." onClose={onClose} wide><div className="settings-tabs"><button className={tab==='voice'?'active':''} onClick={()=>setTab('voice')}><AudioLines size={16}/>Voz e inteligência</button><button className={tab==='drive'?'active':''} onClick={()=>setTab('drive')}><Cloud size={16}/>Google Drive</button><button className={tab==='storage'?'active':''} onClick={()=>setTab('storage')}><HardDrive size={16}/>Armazenamento</button></div>
    {tab==='voice'&&<div className="settings-body"><div className="notice"><ShieldCheck size={20}/><div><strong>Assinatura do chat ≠ acesso à API</strong><p>Gemini Pro e ChatGPT Pro não fornecem, por si só, uma API para este aplicativo. Use uma chave oficial do AI Studio/OpenAI ou um reconhecedor disponível no computador.</p></div></div><label>Serviço de transcrição</label><div className="provider-grid">{(['browser','windows','gemini','openai'] as Provider[]).map(p=><button key={p} className={`provider-card ${provider===p?'selected':''}`} onClick={()=>setProvider(p)}><span className="provider-icon">{p==='gemini'?<Sparkles/>:p==='openai'?<AudioLines/>:p==='windows'?<Monitor/>:<Mic/>}</span><strong>{PROVIDER_NAMES[p]}</strong><small>{p==='browser'?'Sem chave · depende do navegador':p==='windows'?'Local · requer reconhecedor pt-BR':'Chave de API · pode gerar custos'}</small>{provider===p&&<CheckCircle2 size={16} className="provider-check"/>}</button>)}</div>
      {provider==='browser'&&<p className="muted settings-note">O reconhecimento Web Speech depende do suporte do navegador e pode usar os serviços online dele. Se falhar, o áudio continua gravado. Não é uma garantia de transcrição offline.</p>}
      {provider==='windows'&&<div className="notice"><Monitor size={19}/><p>{config.native.available&&config.native.speechLanguages.includes('pt-BR')?'Reconhecedor Windows pt-BR detectado. Disponível ao capturar pelo companheiro Windows.':'Reconhecedor Windows pt-BR não detectado. Use o pacote portátil em uma máquina com esse reconhecedor ou escolha outra opção.'}</p></div>}
      {['gemini','openai'].includes(provider)&&<><label htmlFor="api-key">Chave da {provider==='gemini'?'Gemini':'OpenAI'} API <span className="label-note">somente na memória desta sessão</span></label><input id="api-key" type="password" value={key} onChange={e=>setKey(e.target.value)} autoComplete="off" placeholder={config.configured?'Uma chave já está configurada. Preencha para substituir.':'Cole sua chave oficial de API'}/><p className="field-help">A chave fica no servidor local, nunca no backup, no Drive ou no armazenamento do navegador. Ao reiniciar o aplicativo será necessário informá-la novamente, salvo configuração por variável de ambiente.</p>{provider==='gemini'&&<div className="form-row"><div><label htmlFor="model">Modelo para imagens e áudio</label><input id="model" value={model} onChange={e=>setModel(e.target.value)}/></div><div><label htmlFor="live-model">Modelo Gemini Live</label><input id="live-model" value={liveModel} onChange={e=>setLiveModel(e.target.value)}/></div></div>}<label className="checkbox-label"><input type="checkbox" checked={consent} onChange={e=>setConsent(e.target.checked)}/><span>Autorizo enviar áudio ao provedor selecionado e capturas quando eu solicitar uma análise por IA.</span></label><p className="field-help">Modelos e cotas dependem do seu projeto. A OpenAI transcreve em blocos de aproximadamente 8 segundos; o Gemini usa uma sessão Live.</p><a className="text-link" href={provider==='gemini'?'https://aistudio.google.com/apikey':'https://platform.openai.com/api-keys'} target="_blank" rel="noreferrer">Abrir configuração oficial da API <ExternalLink size={13}/></a></>}
      <div className="modal-actions"><button className="button ghost" disabled={busy} onClick={()=>void run(async()=>{await api('/api/config/clear',{});setProvider('browser');setConsent(false);setKey('');await refresh();notify('Credencial desta sessão removida.');})}>Remover credencial</button><div>{['gemini','openai'].includes(provider)&&<button className="button secondary" disabled={busy} onClick={()=>void run(async()=>{await save();await api('/api/ai/test',{});notify('Conexão com a API confirmada.');})}>Testar conexão</button>}<button className="button primary" disabled={busy} onClick={()=>void run(async()=>{await save();notify('Preferências de voz salvas.');onClose();})}>{busy?<LoaderCircle className="spin" size={16}/>:<Check size={16}/>}Salvar preferências</button></div></div>
    </div>}
    {tab==='drive'&&<div className="settings-body"><div className="connection-hero"><div className="connection-icon"><Cloud size={34}/></div><div><h3>Seu conhecimento, onde você estiver.</h3><p>Guarde backups completos na pasta Playbook Studio do seu Google Drive.</p></div></div><div className="notice"><ShieldCheck size={20}/><p>O login Google autoriza o Drive. Ele não habilita a Gemini API. A permissão solicitada é <code>drive.file</code>, limitada aos arquivos acessíveis pelo aplicativo.</p></div><label htmlFor="google-client">Client ID OAuth do Google</label><input id="google-client" value={clientId} onChange={e=>setClientId(e.target.value)} placeholder="…apps.googleusercontent.com"/><p className="field-help">Crie um cliente OAuth do tipo Aplicativo da Web no Google Cloud, habilite a Drive API e cadastre a origem <code>{location.origin}</code>. Em modo de teste, adicione sua conta como usuário de teste. Este identificador é público e pode ser salvo no navegador.</p><div className="modal-actions"><button className="button secondary" disabled={busy} onClick={()=>{disconnectDrive();setConnected(false);setDriveFiles([]);notify('Google Drive desconectado.');}}>Desconectar</button><button className="button primary" disabled={busy} onClick={()=>void run(async()=>{localStorage.setItem('playbook-google-client-id',clientId.trim());await connectDrive(clientId.trim());setConnected(true);setDriveFiles(await listDrive());notify('Google Drive conectado.');})}>{busy?<LoaderCircle className="spin" size={16}/>:<Cloud size={16}/>} {connected?'Atualizar arquivos':'Conectar com Google'}</button></div>{driveFiles.length>0&&<div className="drive-list"><h4>Backups disponíveis</h4>{driveFiles.map(f=><div key={f.id}><div><strong>{f.name}</strong><small>{new Date(f.modifiedTime).toLocaleDateString('pt-BR')}</small></div><button className="button small secondary" disabled={busy} onClick={()=>void run(async()=>{await restoreZip(await downloadDrive(f.id));notify('Backup importado. Atualize a biblioteca ao fechar as configurações.');})}><Download size={14}/>Importar</button></div>)}</div>}</div>}
    {tab==='storage'&&<div className="settings-body"><div className="connection-hero"><div className="connection-icon"><HardDrive size={34}/></div><div><h3>Primeiro, no seu computador.</h3><p>Os procedimentos e suas mídias ficam no IndexedDB deste navegador.</p></div></div><p>Os dados ficam vinculados a este endereço e perfil do navegador. Limpar os dados do site pode removê-los. Exporte regularmente um backup completo para uma pasta de sua escolha ou para o Google Drive.</p><div className="notice"><FolderOpen size={20}/><p>O backup <code>.playbook.zip</code> preserva imagens originais, anotações editáveis, áudio e vídeo. O pacote HTML contém as imagens com as ocultações aplicadas, mas áudio e vídeo originais exigem revisão separada.</p></div><p>Uma gravação interrompida é recuperada a partir dos trechos já persistidos. O navegador pode perder o último trecho ainda em memória. Não há sincronização automática nem edição simultânea entre pessoas nesta versão.</p><button className="button secondary" onClick={()=>void run(async()=>{const e=await storageUsage();notify(`Uso aproximado: ${((e.usage||0)/1024/1024).toFixed(1)} MB · Cota: ${((e.quota||0)/1024/1024/1024).toFixed(1)} GB`);})}><HardDrive size={16}/>Consultar espaço disponível</button>{config.portable&&<button className="button ghost" onClick={()=>void run(async()=>{await api('/api/shutdown',{});notify('Aplicativo encerrado. Você pode fechar esta aba e abri-lo novamente pelo executável.');})}>Encerrar aplicativo portátil</button>}</div>}
  </Modal>;
}

export default function App(){
  const [assistant,setAssistant]=useState<AssistantTab>();
  const [books,setBooks]=useState<Playbook[]>([]);const [config,setConfig]=useState<Config>();const [view,setView]=useState('overview');const [role,setRole]=useState<Role|'all'>('all');const [search,setSearch]=useState('');const [status,setStatus]=useState('all');const [active,setActive]=useState<Playbook>();const [selected,setSelected]=useState(0);const [settings,setSettings]=useState(false);const [help,setHelp]=useState(false);const [newRecording,setNewRecording]=useState(false);const [recording,setRecording]=useState(false);const [busy,setBusy]=useState('');const [toast,setToast]=useState('');const [recState,setRecState]=useState({seconds:0,paused:false,level:0,transcript:''});const [recordBook,setRecordBook]=useState<Playbook>();const [exportMenu,setExportMenu]=useState(false);const [tool,setTool]=useState<Tool>('select');const [annotationText,setAnnotationText]=useState('');const [draft,setDraft]=useState<Annotation>();const [saved,setSaved]=useState(true);const [confirm,setConfirm]=useState<{message:string;action:()=>void}>();
  const recorder=useRef<StudioRecorder|null>(null);const preview=useRef<HTMLDivElement>(null);const audioRef=useRef<HTMLAudioElement>(null);const importInput=useRef<HTMLInputElement>(null);const imageInput=useRef<HTMLInputElement>(null);const annotationStart=useRef<{x:number;y:number}|undefined>(undefined);const toastTimer=useRef<ReturnType<typeof setTimeout>|undefined>(undefined);
  const notify=useCallback((message:string)=>{clearTimeout(toastTimer.current);setToast(message);toastTimer.current=setTimeout(()=>setToast(''),7500);},[]);
  const reload=useCallback(async()=>setBooks(await listBooks()),[]);
  const refreshConfig=useCallback(async()=>setConfig(await api<Config>('/api/config')),[]);
  useEffect(()=>{void (async()=>{try{await recoverInterrupted();await reload();await refreshConfig();}catch{notify('Não foi possível abrir o armazenamento ou o serviço local. Verifique se o aplicativo continua em execução.');}})();return()=>clearTimeout(toastTimer.current);},[]);
  useEffect(()=>{if(recording&&preview.current&&recorder.current)preview.current.append(recorder.current.canvas);},[recording]);
  useEffect(()=>{if(config?.native.platform!=='win32'||config.native.available)return;let attempts=0;const timer=setInterval(()=>{if(attempts++>=20)return clearInterval(timer);void refreshConfig().catch(()=>{});},750);return()=>clearInterval(timer);},[config?.native.platform,config?.native.available,refreshConfig]);
  useEffect(()=>{const before=(e:BeforeUnloadEvent)=>{if(recorder.current){e.preventDefault();e.returnValue='';}};window.addEventListener('beforeunload',before);return()=>window.removeEventListener('beforeunload',before);},[]);
  const run=async(label:string,fn:()=>Promise<unknown>)=>{if(busy)return;setBusy(label);try{await fn();}catch(e){notify((e as Error).message||'Não foi possível concluir esta ação.');}finally{setBusy('');}};
  const openBook=(book:Playbook)=>{setActive(book);setSelected(0);setTool('select');setView('editor');setExportMenu(false);};
  const edit=async(book:Playbook)=>{const next={...book,updatedAt:new Date().toISOString()};if(active?.status==='published'&&next.status==='published'){next.status='draft';next.version++;}setActive(next);setSaved(false);try{await saveBook(next);setSaved(true);setBooks(prev=>[next,...prev.filter(b=>b.id!==next.id)]);}catch{notify('Alteração não salva. Verifique o espaço e exporte seu trabalho.');}};
  const applyLocal=async(next:Playbook)=>{const updated={...next,updatedAt:new Date().toISOString(),...(active?.status==='published'?{status:'draft' as const,version:active.version+1}:{})};await saveBook(updated);setActive(updated);setSaved(true);await reload();};
  const editStep=(patch:Partial<Step>)=>{if(!active)return;void edit({...active,steps:active.steps.map((s,i)=>i===selected?{...s,...patch}:s)});};
  const hotkey=useCallback((action:string)=>{const r=recorder.current;if(!r){if(action==='toggle')setNewRecording(true);return;}if(action==='toggle')void r.stop().catch(e=>notify(e.message));if(action==='mark')void r.mark();if(action==='pause')void r.togglePause().catch(e=>notify(e.message));},[notify]);
  useEffect(()=>{const listener=(e:KeyboardEvent)=>{if(e.key==='/'&&!(e.target instanceof HTMLInputElement)&&!(e.target instanceof HTMLTextAreaElement)&&!(e.target instanceof HTMLSelectElement)&&!document.querySelector('dialog[open]')&&!recorder.current){e.preventDefault();(document.querySelector('.search-box input') as HTMLInputElement)?.focus();return;}if(e.ctrlKey&&e.altKey&&['r','m','p'].includes(e.key.toLowerCase())){e.preventDefault();if(!config?.native.available)hotkey(e.key.toLowerCase()==='r'?'toggle':e.key.toLowerCase()==='m'?'mark':'pause');}};window.addEventListener('keydown',listener);return()=>window.removeEventListener('keydown',listener);},[hotkey,config?.native.available]);
  useEffect(()=>{if(!config?.native.available)return;const ws=socket('/native');ws.onmessage=e=>{const event=JSON.parse(e.data);if(event.type==='hotkey'&&!recorder.current)hotkey(event.action);};return()=>ws.close();},[config?.native.available,hotkey]);
  const startRecording=async(title:string,recordRole:Role,source:'browser'|'windows',display:number,automatic:boolean,video:boolean)=>{
    if(!config)return;const book=createBook(title,recordRole);const r=new StudioRecorder(book,{source,display,autoCapture:automatic,video,config},{update:setRecordBook,state:setRecState,error:notify,hotkey,stopped:completed=>{recorder.current=null;setRecording(false);setRecordBook(undefined);openBook(completed);void reload();notify(completed.status==='interrupted'?'Gravação recuperada parcialmente. Houve uma falha de armazenamento; confira as mídias antes de exportar.':'Gravação salva. Revise a transcrição e as capturas antes de publicar.');}});
    recorder.current=r;
    try{await r.start();setNewRecording(false);setRecordBook({...r.book});setRecording(true);notify(source==='windows'?'Gravando o monitor selecionado. Ctrl + Alt + M marca uma etapa.':'Gravando a tela compartilhada. Cliques externos não são detectados neste modo.');}
    catch(e){recorder.current=null;notify((e as Error).name==='NotAllowedError'?'Captura ou microfone não autorizado. Autorize ambos para gravar.':(e as Error).message);void reload();}
  };
  const step=active?.steps[selected];
  const visible=books.filter(b=>(role==='all'||b.role===role)&&(status==='all'||b.status===status)&&`${b.title} ${b.description} ${b.role} ${b.steps.map(s=>s.transcript).join(' ')}`.toLocaleLowerCase('pt-BR').includes(search.toLocaleLowerCase('pt-BR')));
  const minutes=books.reduce((sum,b)=>sum+b.duration,0)/60;
  const publish=()=>{if(!active)return;if(!active.steps.length)return notify('Adicione pelo menos uma etapa antes de publicar.');if(active.steps.some(s=>!s.title.trim()))return notify('Todas as etapas precisam de um título.');void edit({...active,status:'published'});notify('Procedimento publicado na biblioteca local.');};
  const uploadToDrive=()=>{if(!active)return;void run('Enviando backup ao Drive',async()=>{if(!driveConnected())await connectDrive(localStorage.getItem('playbook-google-client-id')||config?.googleClientId||'');const result=await uploadDrive(active);await edit({...active,driveId:result.id,driveSyncedAt:new Date().toISOString()});notify('Backup completo salvo no Google Drive.');});};
  const point=(e:React.PointerEvent<HTMLDivElement>)=>{const r=e.currentTarget.getBoundingClientRect();return{x:Math.max(0,Math.min(1,(e.clientX-r.left)/r.width)),y:Math.max(0,Math.min(1,(e.clientY-r.top)/r.height))};};
  const addAnnotation=(e:React.PointerEvent<HTMLDivElement>)=>{if(tool==='select'||!step)return;e.currentTarget.setPointerCapture(e.pointerId);const p=point(e);annotationStart.current=p;setDraft({id:id(),type:tool,...p,x2:p.x,y2:p.y,text:annotationText});};
  const finishAnnotation=(e:React.PointerEvent<HTMLDivElement>)=>{if(!draft||!step||!annotationStart.current)return;const p=point(e);const tiny=Math.abs(p.x-draft.x)+Math.abs(p.y-draft.y)<.012;const a={...draft,x2:tiny?Math.min(1,draft.x+.07):p.x,y2:tiny?Math.min(1,draft.y+.07):p.y};editStep({annotations:[...step.annotations,a]});setDraft(undefined);annotationStart.current=undefined;};

  return <div className="app-shell"><aside className="sidebar"><button className="brand" onClick={()=>{setView('overview');setRole('all');}}><span className="brand-mark"><BookOpen size={24}/></span><span>playbook<span className="brand-light">studio</span><small>CONHECIMENTO EM MOVIMENTO</small></span></button><div className="workspace"><span className="workspace-avatar">EC</span><div><strong>Equipe comercial</strong><small>Seu espaço de processos</small></div><ChevronDown size={15}/></div><div className="nav-label">PRINCIPAL</div><nav><button className={view==='overview'?'active':''} onClick={()=>{setView('overview');setRole('all');}}><LayoutDashboard size={19}/>Visão geral</button><button className={view==='library'?'active':''} onClick={()=>{setView('library');setRole('all');}}><Library size={19}/>Minha biblioteca <span className="nav-count">{books.length}</span></button><button onClick={()=>setSettings(true)}><Cloud size={19}/>Conexões <span className="tiny-dot"/></button></nav><div className="nav-label roles-label">ÁREAS DA EQUIPE <Users size={13}/></div><nav className="role-nav">{ROLES.map((r,i)=><button key={r} className={role===r&&view!=='editor'?'active':''} onClick={()=>{setRole(r);setView('library');}}><span className={`role-dot role-${i}`}/><span>{r}</span><span className="role-count">{books.filter(b=>b.role===r).length}</span></button>)}</nav><div className="sidebar-bottom"><div className="local-card"><ShieldCheck size={19}/><div><strong>Seu conteúdo é seu.</strong><small>Gravação e biblioteca locais.</small></div></div><button className="settings-nav" onClick={()=>setSettings(true)}><Settings2 size={18}/>Configurações</button><button className="user-profile" onClick={()=>setHelp(true)}><span className="user-avatar">EU</span><span><strong>Meu estúdio</strong><small>Ambiente de trabalho local</small></span><CircleHelp size={17}/></button></div></aside>
  <main className="main"><header className="topbar"><div className="breadcrumb"><span>Workspace</span><ChevronRight size={14}/><strong>{view==='editor'?'Editor de processo':view==='library'?'Minha biblioteca':'Visão geral'}</strong></div><div className="topbar-actions"><span className="local-status"><span/> Armazenamento local</span><button className="icon-button" onClick={()=>setHelp(true)} aria-label="Ajuda"><CircleHelp size={19}/></button><button className="icon-button" onClick={()=>setSettings(true)} aria-label="Configurações do estúdio"><Settings2 size={18}/></button><span className="top-avatar">EU</span></div></header>
  {view!=='editor'?<div className="dashboard"><div className="page-heading"><div><div className="eyebrow">SEU ESTÚDIO DE CONHECIMENTO</div><h1>{view==='overview'?'Boas ideias viram bons processos.':role==='all'?'Minha biblioteca':role}</h1><p>{view==='overview'?'Transforme o que você sabe em passos que toda a equipe pode seguir.':'Encontre, organize e compartilhe o jeito certo de fazer.'}</p></div><button className="button primary" onClick={()=>setNewRecording(true)}><Plus size={18}/>Nova gravação</button></div>
  {view==='overview'&&<section className="hero"><div className="hero-content"><span className="hero-badge"><Sparkles size={13}/>MENOS REPETIÇÃO. MAIS CLAREZA.</span><h2>Você faz. Você explica.<br/><span>O conhecimento fica.</span></h2><p>Capture sua tela, narre o processo e transforme<br className="desktop-break"/> cada ação em um passo a passo visual.</p><div className="hero-actions"><button className="button light" onClick={()=>setNewRecording(true)}><Circle size={16} fill="currentColor"/>Começar uma gravação<ArrowRight size={16}/></button><button className="hero-example" disabled={!!busy} onClick={()=>void run('Preparando exemplo',async()=>{const b=await createDemo();await reload();openBook(b);})}>Explorar um exemplo<MoveUpRight size={14}/></button></div><div className="hero-foot"><Monitor size={14}/><span>Sem instalar para consultar</span><span className="separator-dot">·</span><Mic size={14}/><span>Áudio original preservado</span></div></div><div className="hero-art" aria-hidden="true"><div className="art-orbit orbit-one"/><div className="art-orbit orbit-two"/><div className="mini-window"><div className="mini-top"><i/><i/><i/><span>Seu próximo playbook</span><div className="mini-record"><span/>REC</div></div><div className="mini-body"><div className="mini-sidebar"><div className="mini-logo"/><i/><i/><i/><i/></div><div className="mini-screen"><span className="mock-heading"/><span className="mock-subheading"/><div className="mock-grid"><div/><div/><div/></div><div className="mock-field"><span/><i/></div><div className="mock-field"><span/><i/></div><div className="mock-button"/><div className="mock-cursor"><MousePointer2 size={28} fill="#77b5ff"/></div><span className="mock-ring"/></div></div></div><div className="floating-step"><span className="step-check"><Check size={15}/></span><div><strong>Mais que uma gravação.</strong><small>Um processo que todos entendem.</small></div></div><div className="floating-audio"><Mic size={17}/>{[12,22,15,30,21,36,25,18,29,14,23,12].map((h,i)=><i key={i} style={{height:h}}/>)}<span>Voz + tela</span></div></div></section>}
  <section className="stats-grid"><div className="stat-card"><span className="stat-icon blue"><BookOpen size={19}/></span><div><small>Processos na biblioteca</small><strong>{books.length.toString().padStart(2,'0')}</strong></div></div><div className="stat-card"><span className="stat-icon green"><CheckCircle2 size={19}/></span><div><small>Prontos para compartilhar</small><strong>{books.filter(b=>b.status==='published').length.toString().padStart(2,'0')}</strong></div></div><div className="stat-card"><span className="stat-icon violet"><Users size={19}/></span><div><small>Cargos da equipe</small><strong>06</strong></div></div><div className="stat-card"><span className="stat-icon amber"><AudioLines size={19}/></span><div><small>Minutos documentados</small><strong>{Math.round(minutes).toString().padStart(2,'0')}<span> min</span></strong></div></div></section>
  <section className="library-section"><div className="section-heading"><div><h2>{view==='overview'?'Sua biblioteca de processos':'Procedimentos'}<span className="count-badge">{visible.length}</span></h2><p>O próximo passo da sua equipe começa aqui.</p></div><button className="button ghost" onClick={()=>importInput.current?.click()}><Upload size={16}/>Importar backup</button></div><div className="library-toolbar"><div className="filter-tabs"><button className={status==='all'?'active':''} onClick={()=>setStatus('all')}>Todos</button><button className={status==='published'?'active':''} onClick={()=>setStatus('published')}>Publicados</button><button className={status==='draft'?'active':''} onClick={()=>setStatus('draft')}>Rascunhos</button></div><label className="search-box"><Search size={16}/><input aria-label="Buscar processos" placeholder="Buscar um processo…" value={search} onChange={e=>setSearch(e.target.value)}/><kbd>/</kbd></label><select aria-label="Filtrar por cargo" value={role} onChange={e=>setRole(e.target.value as Role|'all')}><option value="all">Todos os cargos</option>{ROLES.map(r=><option key={r}>{r}</option>)}</select></div>
  {visible.length?<div className="book-grid">{visible.map(book=><article className="book-card" key={book.id}><button className="book-cover" onClick={()=>openBook(book)}><AssetImage assetId={book.steps.find(s=>s.imageId)?.imageId} alt={`Captura de ${book.title}`}/><span className="cover-gradient"/><span className="duration-badge"><Video size={12}/>{formatTime(book.duration)}</span>{book.demo&&<span className="demo-badge">DEMONSTRAÇÃO</span>}<span className="cover-open"><ArrowRight size={20}/></span></button><div className="book-content"><div className="book-tags"><span className="role-tag">{book.role}</span><span className={`status-tag ${book.status}`}><i/>{STATUS[book.status]}</span></div><button className="book-title" onClick={()=>openBook(book)}>{book.title}</button><p>{book.description||`${book.steps.length} etapas para orientar sua equipe com clareza.`}</p><div className="book-footer"><span><FileText size={13}/>{book.steps.length} etapas</span><span>{new Date(book.updatedAt).toLocaleDateString('pt-BR',{day:'2-digit',month:'short'})}</span><button className="icon-button" aria-label={`Excluir ${book.title}`} onClick={()=>setConfirm({message:`Excluir “${book.title}” e suas mídias locais? Esta ação não remove backups já exportados.`,action:()=>void run('Excluindo processo',async()=>{await deleteBook(book.id);await reload();setConfirm(undefined);})})}><Trash2 size={14}/></button></div></div></article>)}</div>:<div className="empty-state"><div className="empty-icon"><BookOpen size={30}/><span><Plus size={13}/></span></div><h3>{search||role!=='all'||status!=='all'?'Nenhum processo encontrado':'Todo grande processo começa com um primeiro passo.'}</h3><p>{search||role!=='all'||status!=='all'?'Experimente ajustar a busca ou os filtros.':'Grave sua primeira demonstração ou explore um exemplo para conhecer o estúdio.'}</p><div><button className="button secondary" onClick={()=>void run('Preparando exemplo',async()=>{const b=await createDemo();await reload();openBook(b);})}>Explorar exemplo<ArrowRight size={15}/></button><button className="button primary" onClick={()=>setNewRecording(true)}><Plus size={16}/>Criar meu primeiro processo</button></div></div>}
  </section><div className="dashboard-footer"><span><ShieldCheck size={14}/>Feito para registrar conhecimento, respeitando seus dados.</span><span>Playbook Studio <i>v0.2</i></span></div></div>:
  active&&<div className="editor"><div className="editor-heading"><div className="editor-title"><button className="icon-button" aria-label="Voltar para a biblioteca" onClick={()=>{setView('library');void reload();}}><ArrowLeft size={21}/></button><div><span className="eyebrow">EDITOR DE PROCEDIMENTO {active.demo?'· DEMONSTRAÇÃO':''}</span><input aria-label="Título do procedimento" value={active.title} onChange={e=>void edit({...active,title:e.target.value})}/><small className="save-status">{saved?<Check size={12}/>:<LoaderCircle size={12}/>} {saved?'Salvo neste navegador':'Salvando…'} · Versão {active.version}</small></div></div><div className="editor-actions"><button className="button secondary local-assistant-button" onClick={()=>{setExportMenu(false);setAssistant('suggestions');}}><Sparkles size={16}/>Organizar sem API</button><button className="button secondary" disabled={!!busy} onClick={uploadToDrive}><CloudUpload size={16}/><span>Drive</span></button><div className="export-wrap"><button className="button secondary" onClick={()=>setExportMenu(!exportMenu)}><Download size={16}/>Exportar<ChevronDown size={14}/></button>{exportMenu&&<div className="dropdown">{[['PDF','Documento para leitura e impressão',()=>exportPdf(active)],['Word','Arquivo .docx editável',()=>exportWord(active)],['HTML multimídia','Tutorial com áudio e vídeo originais',()=>exportHtml(active)],['Backup completo','Inclui originais e marcações editáveis',async()=>download(await backupZip(active),`${safeName(active.title)}.playbook.zip`)]].map(([name,description,action])=><button key={name as string} onClick={()=>{setExportMenu(false);void run(`Exportando ${name}`,action as ()=>Promise<unknown>);}}><FileText size={16}/><span><strong>{name as string}</strong><small>{description as string}</small></span></button>)}</div>}</div><button className="button primary" onClick={publish}><CheckCircle2 size={16}/>{active.status==='published'?'Publicado':'Publicar'}</button></div></div>
  {reviewIssues(active).length>0&&<button className="review-banner" onClick={()=>setAssistant('review')}><CircleHelp size={16}/><span>{reviewIssues(active).length} ponto(s) para revisar antes de compartilhar</span><ChevronRight size={15}/></button>}
  <div className="editor-meta"><label>Cargo<select value={active.role} onChange={e=>void edit({...active,role:e.target.value as Role})}>{ROLES.map(r=><option key={r}>{r}</option>)}</select></label><label className="description-field">Objetivo do procedimento<input value={active.description} placeholder="O que a equipe aprenderá neste processo?" onChange={e=>void edit({...active,description:e.target.value})}/></label></div>
  <div className="editor-layout"><aside className="steps-panel"><div className="steps-panel-heading"><strong>Etapas <span>{active.steps.length}</span></strong><button className="icon-button" aria-label="Adicionar etapa" onClick={()=>{const s:Step={id:id(),title:`Etapa ${active.steps.length+1}`,transcript:'',instruction:'',time:active.duration,endTime:active.duration,annotations:[],source:'manual'};void edit({...active,steps:[...active.steps,s]});setSelected(active.steps.length);}}><Plus size={17}/></button></div><div className="steps-list">{active.steps.map((s,i)=><button key={s.id} className={`step-item ${i===selected?'selected':''}`} onClick={()=>{setSelected(i);setDraft(undefined);}}><div className="step-thumb"><AssetImage assetId={s.imageId} alt=""/><span>{String(i+1).padStart(2,'0')}</span></div><div><strong>{s.title}</strong><small>{formatTime(s.time)}<span>·</span>{s.source==='click'?'Clique':s.source==='manual'?'Manual':s.source==='demo'?'Exemplo':'Captura automática'}</small></div></button>)}</div><button className="add-step" onClick={()=>imageInput.current?.click()}><Upload size={15}/>Adicionar captura</button></aside>
  <div className="step-editor">{step?<><div className="step-heading"><span className="step-number">ETAPA {String(selected+1).padStart(2,'0')}</span><div><button className="icon-button" aria-label="Mover etapa para cima" disabled={selected===0} onClick={()=>{const steps=[...active.steps];[steps[selected-1],steps[selected]]=[steps[selected],steps[selected-1]];void edit({...active,steps});setSelected(selected-1);}}><ArrowUp size={15}/></button><button className="icon-button" aria-label="Mover etapa para baixo" disabled={selected===active.steps.length-1} onClick={()=>{const steps=[...active.steps];[steps[selected],steps[selected+1]]=[steps[selected+1],steps[selected]];void edit({...active,steps});setSelected(selected+1);}}><ArrowDown size={15}/></button><button className="icon-button danger" aria-label="Excluir etapa" onClick={()=>setConfirm({message:'Excluir esta etapa? As mídias originais permanecem no backup completo.',action:()=>{void edit({...active,steps:active.steps.filter((_,i)=>i!==selected)});setSelected(Math.max(0,selected-1));setConfirm(undefined);}})}><Trash2 size={15}/></button></div></div><input className="step-title-input" aria-label="Título da etapa" value={step.title} onChange={e=>editStep({title:e.target.value})}/><div className="annotation-toolbar"><div>{([['select',MousePointer2,'Selecionar'],['circle',Circle,'Círculo'],['arrow',MoveUpRight,'Seta'],['box',SquareDashed,'Retângulo'],['blur',EyeOff,'Ocultar dados'],['label',FileText,'Anotação']] as const).map(([value,Icon,label])=><button key={value} className={tool===value?'active':''} title={label} aria-label={label} onClick={()=>setTool(value)}><Icon size={17}/></button>)}<span className="toolbar-divider"/><button title="Desfazer marcação" aria-label="Desfazer marcação" disabled={!step.annotations.length} onClick={()=>editStep({annotations:step.annotations.slice(0,-1)})}><Undo2 size={17}/></button></div><button className="button ai-button" disabled={!!busy||!step.imageId} onClick={()=>void run('Analisando captura com IA',async()=>{if(!step.imageId)return;const asset=await getAsset(step.imageId);if(!asset)throw new Error('Captura não encontrada.');const result=await api<{title:string;instruction:string;annotations:Omit<Annotation,'id'>[]}>('/api/enhance',{image:await blobDataURL(await annotatedImage(step.imageId,step.annotations.filter(a=>a.type==='blur'))),transcript:step.transcript,title:step.title});editStep({title:result.title,instruction:result.instruction,annotations:[...step.annotations,...result.annotations.map(a=>({...a,id:id()}))]});notify('Sugestões da IA aplicadas. Revise as marcações e o texto.');})}><WandSparkles size={15}/>Sugerir com IA</button></div>
  {tool!=='select'&&<div className="tool-hint"><span>{tool==='blur'?'Arraste para cobrir informações com uma tarja opaca.':tool==='arrow'?'Arraste da origem até o ponto que deseja indicar.':'Arraste sobre a imagem para adicionar a marcação.'}</span><input aria-label="Texto da marcação" placeholder="Rótulo opcional" value={annotationText} onChange={e=>setAnnotationText(e.target.value)}/></div>}
  {step.imageId?<div className={`editor-image tool-${tool}`} onPointerDown={addAnnotation} onPointerMove={e=>{if(draft)setDraft({...draft,x2:point(e).x,y2:point(e).y});}} onPointerUp={finishAnnotation} onPointerCancel={()=>{setDraft(undefined);annotationStart.current=undefined;}}><AssetImage assetId={step.imageId} alt={`Captura: ${step.title}`} draggable={false}/><Annotations annotations={step.annotations} draft={draft}/></div>:<button className="capture-placeholder" onClick={()=>imageInput.current?.click()}><Monitor size={36}/><strong>Adicione a captura desta etapa</strong><span>PNG ou JPEG, até 15 MB</span></button>}
  <div className="image-caption"><span><ShieldCheck size={12}/>Original preservado · marcações editáveis</span><button onClick={()=>imageInput.current?.click()}>Substituir captura</button></div><div className="text-panels"><label><span><Mic size={15}/>Narração literal</span><textarea aria-label="Narração literal" value={step.transcript} placeholder="A transcrição desta etapa aparecerá aqui. Você também pode preencher ou corrigir o texto." onChange={e=>editStep({transcript:e.target.value})}/><small>Correções aqui não alteram o áudio original.</small></label><label><span><Sparkles size={15}/>Instrução para a equipe</span><textarea aria-label="Instrução para a equipe" value={step.instruction} placeholder="Explique a ação e o resultado esperado, ou solicite uma sugestão à IA." onChange={e=>editStep({instruction:e.target.value})}/><small>Versão organizada para facilitar a leitura.</small></label></div><div className="step-timing"><label>Início (segundos)<input type="number" min="0" max={active.duration||undefined} step="0.1" value={step.time} onChange={e=>editStep({time:Math.max(0,Number(e.target.value))})}/></label><label>Fim (segundos)<input type="number" min={step.time} max={active.duration||undefined} step="0.1" value={step.endTime} onChange={e=>editStep({endTime:Math.max(step.time,Number(e.target.value))})}/></label>{active.audioId&&<button className="button secondary" onClick={()=>{if(audioRef.current){audioRef.current.currentTime=step.time;void audioRef.current.play().catch(()=>notify('Não foi possível reproduzir o áudio.'));}}}><Volume2 size={15}/>Ouvir esta etapa</button>}{active.videoId&&<button className="button secondary" disabled={!!busy} onClick={()=>void run('Gerando clipe — aguarde a reprodução do trecho',async()=>{const end=Math.min(step.endTime,step.time+8);if(end<=step.time)throw new Error('Ajuste o início e o fim desta etapa.');const clipId=await createClip(active.videoId!,active.id,step.time,end);editStep({clipId,clipFormat:'video',clipStart:step.time,clipEnd:end});notify('Clipe gerado na resolução da gravação.');})}><Video size={15}/>Gerar clipe de até 8s</button>}{active.videoId&&<button className="button secondary" disabled={!!busy} onClick={()=>void run('Gerando GIF na resolução disponível (até 1080p)',async()=>{const end=Math.min(step.endTime,step.time+4);if(end<=step.time)throw new Error('Ajuste o início e fim da etapa.');const clipId=await createGif(active.videoId!,active.id,step.time,end);editStep({clipId,clipFormat:'gif',clipStart:step.time,clipEnd:end});notify('GIF gerado. Revise o conteúdo antes de compartilhar.');})}><Video size={15}/>Gerar GIF</button>}</div>{step.clipId&&<div className="clip-panel">{step.clipFormat==='gif'?<AssetImage assetId={step.clipId} alt="GIF da etapa"/>:<AssetMedia assetId={step.clipId} type="video"/>}<button className="button secondary" onClick={()=>void run('Baixando clipe',async()=>{const a=await getAsset(step.clipId);if(a)download(a.blob,`etapa-${selected+1}.${a.blob.type.includes('gif')?'gif':a.blob.type.includes('mp4')?'mp4':'webm'}`);})}><Download size={15}/>Baixar clipe</button></div>}</>:<div className="empty-editor"><BookOpen size={35}/><h3>Seu processo está pronto para ganhar forma.</h3><p>Adicione uma etapa pelo botão + ou importe uma captura.</p></div>}
  </div></div>{active.audioId&&<div className="original-audio"><span className="audio-icon"><AudioLines size={21}/></span><div><strong>Áudio original</strong><small>Fonte preservada da sua narração</small></div><AssetMedia assetId={active.audioId} type="audio" audioRef={audioRef}/><button className="icon-button" aria-label="Baixar áudio original" onClick={()=>void run('Baixando áudio original',async()=>{const a=await getAsset(active.audioId);if(a)download(a.blob,`${safeName(active.title)} - audio.${a.blob.type.includes('gif')?'gif':a.blob.type.includes('mp4')?'mp4':'webm'}`);})}><Download size={18}/></button></div>}{active.videoId&&<details className="original-video"><summary><Video size={16}/>Gravação original da tela</summary><AssetMedia assetId={active.videoId} type="video"/><p>As ocultações das imagens não modificam este vídeo original. Revise antes de compartilhar.</p></details>}</div>}
  </main>
  <input ref={importInput} className="hidden-input" type="file" accept=".zip" onChange={e=>{const f=e.target.files?.[0];if(f)void run('Validando e importando backup',async()=>{const b=await restoreZip(f);await reload();openBook(b);notify('Backup importado com integridade verificada.');});e.target.value='';}}/>
  <input ref={imageInput} className="hidden-input" type="file" accept="image/png,image/jpeg,image/webp" onChange={e=>{const f=e.target.files?.[0];if(f&&active)void run('Adicionando captura',async()=>{if(f.size>15*1024*1024)throw new Error('A imagem deve ter até 15 MB.');if(!['image/png','image/jpeg','image/webp'].includes(f.type))throw new Error('Escolha uma imagem PNG, JPEG ou WebP.');const bitmap=await createImageBitmap(f);if(bitmap.width*bitmap.height>40000000){bitmap.close();throw new Error('Imagem grande demais: limite de 40 megapixels.');}bitmap.close();const imageId=id();await saveAsset({id:imageId,bookId:active.id,kind:'image',blob:f,createdAt:Date.now()});if(step)editStep({imageId,annotations:[]});else{await edit({...active,steps:[...active.steps,{id:id(),title:'Nova etapa',transcript:'',instruction:'',time:0,endTime:0,imageId,annotations:[],source:'manual'}]});setSelected(active.steps.length);}});e.target.value='';}}/>
  {assistant&&active&&<LocalAssistantModal book={active} initialTab={assistant} onClose={()=>setAssistant(undefined)} onApply={applyLocal} onSelect={setSelected} notify={notify}/>}
  {settings&&config&&<SettingsModal config={config} refresh={refreshConfig} onClose={()=>{setSettings(false);void reload();}} notify={notify}/>}
  {newRecording&&config&&<RecordingSetup config={config} initialRole={role==='all'?'SDR':role} onClose={()=>setNewRecording(false)} onStart={startRecording} onSettings={()=>{setNewRecording(false);setSettings(true);}}/>}
  {recording&&<div className="recording-overlay"><header><div className="brand compact"><span className="brand-mark"><BookOpen size={23}/></span><span>playbook<span className="brand-light">studio</span></span></div><span className={`recording-indicator ${recState.paused?'paused':''}`}><i/>{recState.paused?'EM PAUSA':'GRAVAÇÃO EM ANDAMENTO'}</span><strong className="recording-time">{formatTime(recState.seconds)}</strong></header><div className="recording-content"><div className="recording-main"><div className="recording-preview" ref={preview}><div className="preview-label"><Monitor size={14}/>{recordBook?.recordingSource==='windows'?'Monitor Windows · cliques detectados':'Tela compartilhada · captura visual'}</div></div><div className="recording-controls"><div className="mic-level"><Mic size={18}/>{Array.from({length:18},(_,i)=><i key={i} className={i<recState.level*18?'lit':''}/>)}<span>Microfone</span></div><button className="button secondary" onClick={()=>void recorder.current?.togglePause().catch(e=>notify(e.message))}>{recState.paused?<Play size={17}/>:<Pause size={17}/>} {recState.paused?'Continuar':'Pausar'}<kbd>Ctrl Alt P</kbd></button><button className="button secondary" disabled={recState.paused} onClick={()=>void recorder.current?.mark()}><Plus size={17}/>Marcar etapa<kbd>Ctrl Alt M</kbd></button><button className="button record-stop" disabled={!!busy} onClick={()=>void run('Finalizando e salvando gravação',()=>recorder.current?.stop()||Promise.resolve())}><Square size={13} fill="currentColor"/>Finalizar</button></div><div className="recording-transcript"><span className="eyebrow"><AudioLines size={15}/>NARRAÇÃO AO VIVO</span><p>{recordBook?.transcript.map(t=>t.text).join(' ')}<span className="interim"> {recState.transcript}</span>{!recordBook?.transcript.length&&!recState.transcript&&<span className="muted">Comece a explicar o processo. O áudio está sendo preservado mesmo se a transcrição estiver indisponível.</span>}</p></div></div><aside className="recording-steps"><div><h3>Seu processo está nascendo</h3><p>{recordBook?.steps.length||0} capturas na sequência</p></div>{recordBook?.steps.map((s,i)=><div className="recorded-step" key={s.id}><span>{String(i+1).padStart(2,'0')}</span><AssetImage assetId={s.imageId} alt="Captura registrada"/><div><strong>{s.title}</strong><small>{formatTime(s.time)}</small></div></div>)}</aside></div><footer><ShieldCheck size={14}/>Áudio e mídias salvos em trechos neste navegador.<span>Fale naturalmente. Faça uma ação por vez. Marque os momentos importantes.</span></footer></div>}
  {help&&<Modal title="Um processo claro começa aqui." subtitle="Seu guia rápido do Playbook Studio." onClose={()=>setHelp(false)}><div className="settings-body help-content">{[['1','Grave e narre','Dê um nome ao processo, selecione o cargo e autorize o microfone e a tela. No Windows portátil, escolha um monitor para registrar os cliques.'],['2','Revise e destaque','Corrija a transcrição, reorganize as etapas e desenhe setas, círculos e ocultações. A IA pode sugerir marcações quando uma API estiver configurada.'],['3','Exporte e preserve','Gere PDF pela impressão do navegador, Word, tutorial HTML ou backup completo. O Drive exige um projeto OAuth próprio.']].map(([n,t,d])=><div className="help-step" key={n}><span>{n}</span><div><h3>{t}</h3><p>{d}</p></div></div>)}<div className="notice"><Keyboard size={20}/><p><strong>Ctrl + Alt + R</strong> abrir preparação / finalizar<br/><strong>Ctrl + Alt + M</strong> marcar etapa<br/><strong>Ctrl + Alt + P</strong> pausar / continuar<br/>Atalhos globais exigem o companheiro Windows. No navegador, a página precisa estar em foco.</p></div><p className="muted">A transcrição do navegador e os serviços de IA dependem de suporte, conexão e permissões. Nenhuma assinatura de chat é usada como chave de API.</p></div></Modal>}
  {confirm&&<Modal title="Confirmar ação" onClose={()=>setConfirm(undefined)}><div className="settings-body"><p>{confirm.message}</p><div className="modal-actions"><button className="button secondary" onClick={()=>setConfirm(undefined)}>Cancelar</button><button className="button danger-button" onClick={confirm.action}>Confirmar exclusão</button></div></div></Modal>}
  {busy&&<div className="busy-indicator" role="status"><LoaderCircle size={18} className="spin"/>{busy}</div>}
  {toast&&<div className="toast" role="status"><span className="toast-icon"><CircleHelp size={18}/></span><p>{toast}</p><button className="icon-button" aria-label="Dispensar aviso" onClick={()=>setToast('')}><X size={16}/></button></div>}
  </div>;
}

function RecordingSetup({config,initialRole,onClose,onStart,onSettings}:{config:Config;initialRole:Role;onClose:()=>void;onStart:(title:string,role:Role,source:'browser'|'windows',display:number,automatic:boolean,video:boolean)=>Promise<void>;onSettings:()=>void}){
  const [title,setTitle]=useState('');const [role,setRole]=useState<Role>(initialRole);const [source,setSource]=useState<'browser'|'windows'>(config.native.available?'windows':'browser');const [display,setDisplay]=useState(config.native.displays.find(d=>d.primary)?.id||0);const [automatic,setAutomatic]=useState(true);const [video,setVideo]=useState(true);const [starting,setStarting]=useState(false);
  return <Modal title="O próximo processo começa com você." subtitle="Prepare a captura. Depois, é só fazer e explicar." onClose={()=>{if(!starting)onClose();}}><form className="settings-body" onSubmit={e=>{e.preventDefault();setStarting(true);void onStart(title,role,source,display,automatic,video).finally(()=>setStarting(false));}}><label htmlFor="record-title">Nome do procedimento</label><input id="record-title" required autoFocus maxLength={160} placeholder="Ex.: Como cadastrar uma oportunidade" value={title} onChange={e=>setTitle(e.target.value)}/><label htmlFor="record-role">Para quem é este processo?</label><select id="record-role" value={role} onChange={e=>setRole(e.target.value as Role)}>{ROLES.map(r=><option key={r}>{r}</option>)}</select><label>Como você quer capturar?</label><div className="capture-modes"><button type="button" className={source==='browser'?'selected':''} onClick={()=>setSource('browser')}><Monitor size={21}/><strong>Compartilhar tela</strong><small>Escolha uma tela, janela ou aba.</small></button><button type="button" disabled={!config.native.available} className={source==='windows'?'selected':''} onClick={()=>setSource('windows')}><MousePointer2 size={21}/><strong>Windows completo</strong><small>{config.native.available?'Cliques, ponteiro e atalhos globais.':'Disponível no pacote portátil Windows.'}</small></button></div>{source==='windows'&&<><label htmlFor="display">Monitor</label><select id="display" value={display} onChange={e=>setDisplay(Number(e.target.value))}>{config.native.displays.map(d=><option key={d.id} value={d.id}>Monitor {d.id+1} · {d.width} × {d.height}{d.primary?' · principal':''}</option>)}</select><p className="field-help">A captura Windows usa quadros de tela a até 4 fps; indicada para procedimentos, não para vídeo de movimento rápido. O ponteiro e os realces aparecem na gravação.</p></>}{source==='browser'&&<p className="field-help">O navegador não detecta cliques em outros programas. As etapas serão sugeridas pelas mudanças visuais e por suas marcações manuais.</p>}<div className="record-options"><label className="checkbox-label"><input type="checkbox" checked={automatic} onChange={e=>setAutomatic(e.target.checked)}/>Sugerir capturas quando a tela mudar</label><label className="checkbox-label"><input type="checkbox" checked={video} onChange={e=>setVideo(e.target.checked)}/>Preservar vídeo da tela para gerar clipes</label></div><div className="voice-summary"><span className="stat-icon blue"><Mic size={18}/></span><div><strong>{PROVIDER_NAMES[config.provider]}</strong><small>{config.provider==='browser'?'Disponibilidade depende do navegador.':config.provider==='windows'?'Requer reconhecedor pt-BR e captura Windows.':config.configured&&config.consent?'Envio de áudio à API autorizado.':'API não configurada: o áudio original será preservado.'}</small></div><button type="button" onClick={onSettings}>Alterar</button></div><p className="field-help">O microfone padrão do Windows será usado. Antes de gravar, feche telas com informações que não devem aparecer no procedimento.</p><div className="modal-actions"><button type="button" className="button secondary" disabled={starting} onClick={onClose}>Cancelar</button><button className="button primary" type="submit" disabled={starting||!title.trim()}>{starting?<LoaderCircle size={17} className="spin"/>:<Circle size={15} fill="currentColor"/>}{starting?'Preparando captura…':'Iniciar gravação'}</button></div></form></Modal>;
}
